SELECT wa.source_id first,wb.source_id second,c.source_id code FROM node p JOIN edge a ON a.t=p.id AND a.r='ABOUT_PRODUCT' JOIN edge b ON b.s=a.s AND b.r='TARGET_ATC' JOIN edge d ON d.t=b.t AND d.r='TARGET_ATC' JOIN edge e ON e.s=d.s AND e.r='ABOUT_PRODUCT' AND e.t=p.id JOIN node wa ON wa.id=a.s AND wa.label='Association' JOIN node c ON c.id=b.t AND c.label='ATCConcept' JOIN node wb ON wb.id=d.s AND wb.label='Association' WHERE p.label='ProductRef' AND p.source_id=:product AND wa.source_id<wb.source_id;
